<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';
$user=x1_require_auth();
$page=preg_replace('/[^a-z_]/','',(string)($_GET['page']??'dashboard')) ?: 'dashboard';
$allowedPages=['dashboard','portals','runtime','devices','announcements','reports','audit'];
if(!in_array($page,$allowedPages,true)) $page='dashboard';

if($_SERVER['REQUEST_METHOD']==='POST'){
    x1_verify_csrf();
    $action=(string)($_POST['action']??'');
    try{
        if($action==='save_runtime'){
            $keys=['maintenance_mode','maintenance_title','maintenance_body','advertisement_status','advertisement_viewable_rate','advertisement_message','intro_url','rate_url','update_package','update_url','vpn_status','vpn_profile_url','sports_url','note_message'];
            foreach($keys as $k){$v=(string)($_POST[$k]??''); if(in_array($k,['maintenance_mode','advertisement_status','vpn_status'],true)){$v=$v==='on'?'on':'off';} x1_set_setting($k,mb_substr(trim($v),0,2000));}
            x1_audit('runtime.settings_saved',['by'=>$user['id']]); x1_flash('Runtime settings saved.');
            header('Location: studio.php?page=runtime'); exit;
        }
        if($action==='add_portal'){
            $url=trim((string)($_POST['url']??''));
            if(!preg_match('#^https?://#i',$url)) throw new RuntimeException('Portal must start with http:// or https://');
            $s=x1_db()->prepare('INSERT INTO portals(url,enabled) VALUES(:u,1)'); $s->bindValue(':u',rtrim($url,'/'),SQLITE3_TEXT); $s->execute();
            x1_audit('portal.created',['url'=>rtrim($url,'/')]); x1_flash('Portal added.');
            header('Location: studio.php?page=portals'); exit;
        }
        if($action==='toggle_portal'){
            $id=(int)($_POST['id']??0); $s=x1_db()->prepare('UPDATE portals SET enabled=CASE enabled WHEN 1 THEN 0 ELSE 1 END WHERE id=:id'); $s->bindValue(':id',$id,SQLITE3_INTEGER); $s->execute();
            x1_audit('portal.toggled',['id'=>$id]); header('Location: studio.php?page=portals'); exit;
        }
        if($action==='delete_portal'){
            $id=(int)($_POST['id']??0); $s=x1_db()->prepare('DELETE FROM portals WHERE id=:id'); $s->bindValue(':id',$id,SQLITE3_INTEGER); $s->execute();
            x1_audit('portal.deleted',['id'=>$id]); header('Location: studio.php?page=portals'); exit;
        }
        if($action==='add_announcement'){
            $title=mb_substr(trim((string)($_POST['title']??'')),0,160); $message=mb_substr(trim((string)($_POST['message']??'')),0,2000);
            if($title===''||$message==='') throw new RuntimeException('Title and message are required.');
            $s=x1_db()->prepare('INSERT INTO announcements(title,message,created_on) VALUES(:t,:m,datetime("now"))'); $s->bindValue(':t',$title,SQLITE3_TEXT);$s->bindValue(':m',$message,SQLITE3_TEXT);$s->execute();
            x1_audit('announcement.created',['title'=>$title]); header('Location: studio.php?page=announcements'); exit;
        }
    }catch(Throwable $e){ x1_flash('Error: '.$e->getMessage()); header('Location: studio.php?page='.$page); exit; }
}

function rows(string $sql): array { $out=[]; $r=x1_db()->query($sql); while($x=$r->fetchArray(SQLITE3_ASSOC))$out[]=$x; return $out; }
$portals=rows('SELECT * FROM portals ORDER BY id DESC');
$devices=rows('SELECT * FROM devices ORDER BY COALESCE(last_seen_at,created_at) DESC LIMIT 100');
$announcements=rows('SELECT a.*, (SELECT COUNT(*) FROM announcement_views v WHERE v.announcement_id=a.id) views FROM announcements a ORDER BY id DESC LIMIT 100');
$reports=rows('SELECT * FROM reports ORDER BY id DESC LIMIT 100');
$audit=rows('SELECT * FROM audit_log ORDER BY id DESC LIMIT 100');
$flash=x1_flash();

function nav(string $p,string $label,string $current): string { $a=$p===$current?' active':''; return '<a class="'.$a.'" href="studio.php?page='.x1_e($p).'"><span>'.x1_e($label).'</span></a>'; }
